{{-- AI Verify: drawer + button colouring. Included once on the orders list and on the order page. Buttons: .ai-btn[data-id]. --}}
<style>
.ai-btn{grid-column:1/-1}
td.action-column .order-action-grid .ai-btn{background:#F1EBFF!important;border:1px solid #CDB9FF!important;color:#3B1D8A!important;font-weight:700}
td.action-column .order-action-grid .ai-btn:hover{background:#E6DAFF!important}
td.action-column .order-action-grid .ai-btn.s-verified{background:#E8F8EF!important;border-color:#86D9A9!important;color:#047857!important}
td.action-column .order-action-grid .ai-btn.s-review{background:#FFF6E0!important;border-color:#F2C46B!important;color:#92400E!important}
td.action-column .order-action-grid .ai-btn.s-high{background:#FEECEC!important;border-color:#F3A0A0!important;color:#B91C1C!important}
td.action-column .order-action-grid .ai-btn.s-failed{background:#FBE0E0!important;border-color:#D96A6A!important;color:#7F1D1D!important}
td.action-column .order-action-grid .ai-btn.s-pending{background:#EEF2F7!important;border-color:#C5CFDC!important;color:#475569!important}
.aiv-ov{position:fixed;inset:0;background:rgba(15,23,42,.45);z-index:9998;display:none}.aiv-ov.on{display:block}
.aiv,.aiv *{box-sizing:border-box}
.aiv{position:fixed;top:0;right:0;bottom:0;width:min(760px,100vw);max-width:100vw;background:#fff;z-index:9999;box-shadow:-12px 0 40px rgba(15,23,42,.25);display:flex;flex-direction:column;transform:translateX(102%);transition:transform .25s;overflow:hidden;font-size:14px;color:#0F172A}.aiv.on{transform:none}
.aiv-h{display:flex;align-items:flex-start;gap:14px;padding:18px 22px 12px;position:relative}
.aiv-lg{width:56px;height:56px;border-radius:14px;background:#F1EBFF;display:flex;align-items:center;justify-content:center;flex:none;color:#5B21B6}.aiv-lg svg{width:32px;height:32px}
.aiv-ht{min-width:0;flex:1;border-left:1px solid #E5E9F0;padding-left:14px}.aiv-ht b{display:block;font-size:clamp(17px,5.5vw,24px);line-height:1.15;color:#1E1B4B;font-weight:800}.aiv-ht small{display:block;color:#64748B;font-size:12.5px;margin-top:4px}
.aiv-x{position:absolute;top:12px;right:14px;border:0;background:none;font-size:26px;line-height:1;color:#DC2626!important;cursor:pointer}
.aiv-tw{padding:0 22px 6px}.aiv-t{display:inline-flex;align-items:center;gap:8px;height:42px;padding:0 18px;border-radius:12px;background:#F1EBFF;border:1px solid #DDD0FF;color:#4C1D95!important;font-size:15px;font-weight:700;text-decoration:none;white-space:nowrap}.aiv-t svg{width:18px;height:18px}
.aiv-b{overflow-y:auto;overflow-x:hidden;padding:10px 22px 20px;flex:1;min-width:0}
.aiv-top{border-radius:14px;padding:14px 16px;display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;border:1px solid;margin-bottom:12px}
.aiv-top.verified{background:#ECFDF5;border-color:#A7F3D0;color:#047857}.aiv-top.review{background:#FFFBEB;border-color:#FDE68A;color:#92400E}.aiv-top.high{background:#FEF2F2;border-color:#FECACA;color:#B91C1C}.aiv-top.failed{background:#FDECEC;border-color:#E8A0A0;color:#7F1D1D}.aiv-top.pending{background:#F1F5F9;border-color:#CBD5E1;color:#475569}
.aiv-sc{font-size:38px;font-weight:800;line-height:1}.aiv-sc small{font-size:14px;font-weight:600;opacity:.7}.aiv-st{font-size:18px;font-weight:800;letter-spacing:.02em;text-transform:uppercase}.aiv-top p{margin:3px 0 0;font-size:13px;opacity:.85;overflow-wrap:anywhere}
.aiv-g{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:10px;margin:0 0 6px}
.aiv-c{display:flex;align-items:center;gap:12px;border:1px solid #E2E8F0;border-radius:14px;padding:10px 12px;background:#fff;box-shadow:0 1px 2px rgba(15,23,42,.04);min-width:0}
.aiv-ic{width:42px;height:42px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex:none}.aiv-ic svg{width:22px;height:22px}
.t-g{background:#DCFCE7;color:#15803D}.t-a{background:#FFEDD5;color:#C2410C}.t-r{background:#FEE2E2;color:#B91C1C}.t-n{background:#EEF2F7;color:#475569}.t-p{background:#EDE9FE;color:#5B21B6}
.aiv-c span{display:block;font-size:11.5px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.03em}
.aiv-c i{font-style:normal;display:inline-block;margin-top:3px;padding:2px 10px;border-radius:8px;font-size:16px;font-weight:800;max-width:100%;overflow-wrap:break-word;word-break:normal;white-space:normal}
.aiv-c i.t-g{background:#DCFCE7}.aiv-c i.t-a{background:#FFEDD5}.aiv-c i.t-r{background:#FEE2E2}.aiv-c i.t-n{background:#EEF2F7;color:#0F172A}.aiv-c i.t-p{background:#EDE9FE}
.aiv h4{margin:18px 0 8px;font-size:15px;text-transform:uppercase;letter-spacing:.04em;color:#4C1D95;font-weight:800}
.aiv-why{display:flex;gap:12px;align-items:flex-start;background:#ECFDF5;border:1px solid #A7F3D0;border-radius:12px;padding:10px 14px;font-size:14px;font-weight:600;color:#14532D}
.aiv-why.w{background:#FFFBEB;border-color:#FDE68A;color:#78350F;flex-direction:column;gap:6px;font-weight:500}.aiv-why.w div{display:flex;gap:8px;overflow-wrap:anywhere}
.aiv-wi{width:30px;height:30px;border-radius:50%;background:#16A34A;color:#fff;display:flex;align-items:center;justify-content:center;flex:none}.aiv-wi svg{width:18px;height:18px}
.aiv .cd{background:none!important;border:0!important;padding:0!important;color:#7C8AA0!important;font-size:10px!important;font-family:ui-monospace,Menlo,monospace;font-weight:600;letter-spacing:.03em;box-shadow:none!important;margin-left:6px}
.aiv-card{border:1px solid #E2E8F0;border-radius:14px;overflow:hidden;background:#fff;margin-bottom:4px}
.aiv-ck{display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:1px solid #EEF2F7}.aiv-ck:last-child{border-bottom:0}
.aiv-ck .aiv-ic{width:40px;height:40px;border-radius:11px}
.aiv-ck>div:nth-child(2){flex:1;min-width:0}.aiv-ck>.aiv-ic,.aiv-ck>.aiv-bd{flex:none}.aiv-ck b{display:block;font-size:15px;color:#0F172A;font-weight:700}.aiv-ck span{display:block;font-size:13.5px;color:#475569;overflow-wrap:anywhere}
.aiv-bd{width:28px;height:28px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex:none;font-weight:800;font-size:15px}.aiv-bd.pass{background:#DCFCE7;color:#15803D}.aiv-bd.review{background:#FEF3C7;color:#B45309}.aiv-bd.fail{background:#FEE2E2;color:#B91C1C}.aiv-bd.info{background:#EEF2F7;color:#64748B}
.aiv-f{display:flex;flex-wrap:wrap;gap:10px;padding:14px 22px;border-top:1px solid #E5E9F0}.aiv-f button{min-width:120px;height:46px;border-radius:12px;font-weight:800;cursor:pointer;font-size:16px;display:flex;align-items:center;justify-content:center;gap:8px}
.aiv-f .p{flex:1.2;background:linear-gradient(90deg,#5B21B6,#7C3AED)!important;color:#fff!important;border:0!important}.aiv-f .p svg{width:20px;height:20px}.aiv-f .c{flex:1;background:#fff!important;color:#0F172A!important;border:1px solid #CBD5E1!important}
.aiv-ovf{border:1px dashed #CBD5E1;border-radius:12px;padding:12px}.aiv-ovf select,.aiv-ovf input{width:100%;height:38px;border:1px solid #CBD5E1;border-radius:8px;padding:0 10px;margin:4px 0;font-size:14px}.aiv-ovf button{height:38px;border-radius:8px;border:1px solid #CBD5E1;background:#fff;color:#0F172A!important;padding:0 16px;font-weight:700;cursor:pointer}
.aiv-h2{width:100%;border-collapse:collapse;table-layout:fixed;font-size:13px}.aiv-h2 td{padding:6px 8px;border-bottom:1px solid #EEF2F7;color:#475569;overflow-wrap:anywhere}
.aiv-ld{padding:50px 10px;text-align:center;color:#64748B;font-size:14px}
.aiv.pg{position:static;transform:none;display:flex;width:100%!important;min-width:0;flex:1 1 100%;max-width:1240px;margin:16px auto;box-shadow:none;border:1px solid #E5E9F0;border-radius:16px;max-height:none;overflow:visible}.aiv.pg .aiv-b{overflow:visible}.aiv.pg .aiv-g{grid-template-columns:repeat(5,minmax(0,1fr))}.aiv.pg .aiv-cks{columns:2;column-gap:24px}.aiv.pg .aiv-cks>*{break-inside:avoid}.aiv.pg .aiv-x,.aiv.pg .aiv-tw,.aiv.pg .aiv-f .c{display:none!important}body.aipg .aiv-ov{display:none!important}
@media(max-width:760px){.aiv.pg .aiv-cks{columns:1}.aiv.pg .aiv-g{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:420px){.aiv-lg{width:40px;height:40px;border-radius:11px}.aiv-lg svg{width:24px;height:24px}.aiv-h{gap:10px;padding-top:14px}.aiv-ht{padding-left:10px}.aiv-ht small{font-size:11.5px}.aiv-x{top:8px;right:8px}.aiv-sc{font-size:26px}.aiv-st{font-size:15px}.aiv-t{width:100%;justify-content:center}.aiv-ck{gap:8px;padding:8px 10px}.aiv-ck .aiv-ic{width:32px;height:32px}.aiv-f button{flex:1 1 100%}}
@media(max-width:560px){.aiv{width:100%}.aiv-ht b{font-size:19px}.aiv-sc{font-size:30px}.aiv-c{padding:8px;gap:8px}.aiv-ic{width:34px;height:34px}.aiv-c i{font-size:14px}.aiv-t{height:38px;font-size:13px;padding:0 12px}.aiv-h,.aiv-tw,.aiv-b,.aiv-f{padding-left:14px;padding-right:14px}}
</style>
<div class="aiv-ov" id="aivOv"></div>
<div class="aiv" id="aiv" role="dialog" aria-hidden="true"><div class="aiv-h"><div class="aiv-lg" id="aivLg"></div><div class="aiv-ht"><b>AI Verification</b><small id="aivSub">Order</small></div><button type="button" class="aiv-x" id="aivX" aria-label="Close">×</button></div><div class="aiv-tw"><a class="aiv-t" id="aivT" href="#" target="_blank" rel="noopener"></a></div><div class="aiv-b" id="aivB"></div><div class="aiv-f"><button type="button" class="p" id="aivRe"></button><button type="button" class="c" id="aivC">Close</button></div></div>
<script>(function(){
var D={verified:'Verified',review:'Review',high:'High Risk',failed:'Failed',pending:'Pending'},IC={verified:'✓',review:'⚠',high:'✕',failed:'✕',pending:'●'},cur=0,tok=function(){var m=document.querySelector('meta[name=csrf-token]');return m?m.content:''};
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
var P={shield:'<path d="M12 3l8 3v6c0 4.5-3.2 8-8 9-4.8-1-8-4.5-8-9V6z"/><path d="M9 12l2 2 4-4"/>',warn:'<path d="M12 3l10 18H2z"/><path d="M12 10v5M12 18v.1"/>',phone:'<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z"/>',layers:'<path d="M12 3l9 5-9 5-9-5z"/><path d="M3 13l9 5 9-5"/>',pin:'<path d="M12 21s7-6.2 7-11a7 7 0 0 0-14 0c0 4.8 7 11 7 11z"/><circle cx="12" cy="10" r="2.5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/>',card:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>',box:'<path d="M12 3l8 4.5v9L12 21l-8-4.5v-9z"/><path d="M12 12l8-4.5M12 12v9M12 12L4 7.5"/>',trend:'<path d="M3 17l6-6 4 4 8-8"/><path d="M15 7h6v6"/>',truck:'<path d="M3 6h11v10H3zM14 9h4l3 3v4h-7"/><circle cx="7.5" cy="17.5" r="1.8"/><circle cx="17.5" cy="17.5" r="1.8"/>',doc:'<path d="M6 3h9l4 4v14H6z"/><path d="M9 12h7M9 16h7"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h3"/>',tag:'<path d="M3 12V4h8l10 10-8 8z"/><circle cx="7.5" cy="8.5" r="1.3"/>',check:'<path d="M5 12.5l4.5 4.5L19 7"/>',dot:'<circle cx="12" cy="12" r="3"/>',spark:'<path d="M12 3l2.1 5.4L20 10l-5.9 1.6L12 17l-2.1-5.4L4 10l5.9-1.6z"/>',ext:'<path d="M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5"/>',ref:'<path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7"/>'};
function ico(n){return'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(P[n]||P.dot)+'</svg>'}
function ckIcon(c){var m=[['PHONE','phone'],['INVALID','phone'],['NAME','user'],['TIER','user'],['ADDRESS','pin'],['RELIAB','shield'],['FRAUD','warn'],['PATTERN','layers'],['CANCEL','layers'],['RETURN','layers'],['DATA','doc'],['DUPLICATE','copy'],['AMOUNT','trend'],['MARGIN','trend'],['PRODUCT','box'],['STOCK','box'],['PAYMENT','card'],['COURIER','truck'],['STATUS','check'],['DISCOUNT','tag'],['CALL','phone'],['CUSTOMER','user'],['LONG','layers'],['NEW','user']];for(var i=0;i<m.length;i++)if(String(c).indexOf(m[i][0])===0||String(c).indexOf(m[i][0])>0)return m[i][1];return'dot'}
var ov=document.getElementById('aivOv'),dr=document.getElementById('aiv'),B=document.getElementById('aivB');
document.getElementById('aivLg').innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+P.shield.replace('<path d="M9 12l2 2 4-4"/>','')+'<path d="M9.5 15v-4l2.5-1.5 2.5 1.5v4M9.5 13.5h5"/></svg>';
document.getElementById('aivT').innerHTML=ico('ext')+'Open in new tab';document.getElementById('aivRe').innerHTML=ico('ref')+'Re-Verify';
function open(){ov.classList.add('on');dr.classList.add('on');dr.setAttribute('aria-hidden','false')}
function close(){ov.classList.remove('on');dr.classList.remove('on');dr.setAttribute('aria-hidden','true')}
ov.onclick=close;document.getElementById('aivX').onclick=close;document.getElementById('aivC').onclick=close;document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});
function paint(btn,st,sc){if(!btn)return;btn.className=btn.className.replace(/\bs-\w+/g,'').trim()+' s-'+st;var t=btn.querySelector('.ai-t');if(t)t.textContent=(IC[st]||'')+' '+(D[st]||'AI Verify')+(sc!=null?' '+sc+'%':'')}
function tone(k,v,raw){v=String(v);if(k==='rel')return raw==null?'n':raw>=80?'g':raw>=60?'a':'r';if(k==='fraud')return/Low/.test(v)?'g':/Medium/.test(v)?'a':/High/.test(v)?'r':'a';if(k==='phone')return v==='Yes'?'g':'n';if(k==='addr')return v==='High'?'g':v==='Medium'?'a':v==='Low'?'r':'n';if(k==='pay')return/Paid/.test(v)?'g':/Due/.test(v)?'a':'n';if(k==='stock')return/Short/.test(v)?'r':'g';if(k==='margin')return/Below/.test(v)?'r':v==='Safe'?'g':'n';if(k==='cour')return v==='-'?'n':parseInt(v,10)>=80?'g':'a';return'n'}
function render(r){var st=r.status,s=r.summary||{};document.getElementById('aivSub').textContent='Order #'+r.order_id+' • '+r.at+' • '+(r.version||'')+' • run '+r.runs;
var h='<div class="aiv-top '+st+'"><div class="aiv-sc">'+r.score+'<small>/100</small></div><div><div class="aiv-st">'+esc(r.label)+'</div><p>Risk: '+esc(r.risk||'-')+(r.override?' • manual override by '+esc(r.override.by):'')+'</p></div></div>';
if(r.override)h+='<div class="aiv-why w" style="margin-bottom:10px"><div>AI result was <b>'+esc(r.ai_label)+'</b>. Staff override to <b>'+esc(r.override.label)+'</b> ('+esc(r.override.by)+', '+esc(r.override.at)+'): '+esc(r.override.reason)+'</div></div>';
function tile(ic,label,val,k,raw){var t=tone(k,val,raw);return'<div class="aiv-c"><div class="aiv-ic t-'+(k==='prev'||k==='tier'?'p':t)+'">'+ico(ic)+'</div><div style="min-width:0"><span>'+label+'</span><i class="t-'+(k==='prev'||k==='tier'?'n':t)+'">'+esc(val)+'</i></div></div>'}
var cs=s.courier_rate!=null?s.courier_rate+'%':'-';
h+='<div class="aiv-g">'+tile('shield','Customer reliability',r.reliability==null?'New':r.reliability+'%','rel',r.reliability)+tile('warn','Fraud risk',(s.fraud_risk||'Unknown')+(r.fraud!=null&&s.fraud_risk!=='Unknown'?' ('+r.fraud+'/100)':''),'fraud')+tile('phone','Phone match',s.phone_match||'-','phone')+tile('layers','Previous orders',s.prev_orders!=null?s.prev_orders:'-','prev')+tile('pin','Address match',s.address||'-','addr')+tile('user','Customer tier',s.tier||'-','tier')+tile('card','Payment',s.payment||'-','pay')+tile('box','Stock',s.stock||'-','stock')+tile('trend','Margin',s.margin||'-','margin')+tile('truck','Courier success',cs,'cour')+'</div>';
h+='<h4>Why?</h4>';var rs=r.reasons||[];
if(rs.length){h+='<div class="aiv-why w">';rs.forEach(function(c){h+='<div><span>'+(c.r==='fail'?'✕':'⚠')+'</span><span>'+esc(c.d)+'<span class="cd">'+esc(c.c)+'</span></span></div>'});h+='</div>'}else h+='<div class="aiv-why"><div class="aiv-wi">'+ico('check')+'</div><div style="align-self:center">Nothing unusual found. Every check passed.</div></div>';
if(s.critical&&s.critical.length)h+='<div class="aiv-why w" style="margin-top:8px;background:#FEF2F2;border-color:#FECACA;color:#7F1D1D"><div>Critical rule(s) forced human review: <b>'+s.critical.map(esc).join(', ')+'</b></div></div>';
h+='<div class="aiv-cks">';var G={};(r.checks||[]).forEach(function(c){(G[c.g]=G[c.g]||[]).push(c)});
['Customer','Fraud','Order','Payment','Courier','Stock','Pricing','History','Communication'].forEach(function(g){if(!G[g])return;h+='<div><h4>'+g+'</h4><div class="aiv-card">';G[g].forEach(function(c){var ic=c.r==='pass'?'✓':c.r==='review'?'⚠':c.r==='fail'?'✕':'i',tc=c.r==='pass'?'g':c.r==='review'?'a':c.r==='fail'?'r':'n';h+='<div class="aiv-ck" title="'+esc(c.c)+'"><div class="aiv-ic t-'+(c.r==='pass'?'p':tc)+'">'+ico(ckIcon(c.c))+'</div><div><b>'+esc(c.t)+'</b><span>'+esc(c.d)+'</span></div><div class="aiv-bd '+c.r+'">'+ic+'</div></div>'});h+='</div></div>'});
h+='</div><h4>Verification history</h4><div class="aiv-card"><table class="aiv-h2">';(r.history||[]).forEach(function(x){h+='<tr><td style="width:34px">#'+x.no+'</td><td>'+esc(x.prev)+' → <b>'+esc(x.status)+'</b> ('+x.score+')</td><td>'+esc(x.by)+'</td><td>'+esc(x.at)+(x.note?'<br>'+esc(x.note):'')+'</td></tr>'});h+='</table></div>';
h+='<p style="font-size:12px;color:#64748B;margin-top:10px">AI Verify supports staff decisions. It never cancels, blocks, refunds or blacklists. Verified ≥ '+r.threshold.verified+', Review ≥ '+r.threshold.review+'.</p>';
if(r.can_override)h+='<h4>Staff override</h4><div class="aiv-ovf"><select id="aivOs"><option value="verified">AI Verified</option><option value="review">Review Required</option><option value="high">High Risk</option><option value="pending">Pending Verification</option></select><input id="aivOr" maxlength="300" placeholder="Override reason (required)"><button type="button" id="aivOk">Save override</button></div>';
B.innerHTML=h;var ok=document.getElementById('aivOk');if(ok)ok.onclick=function(){var rs=document.getElementById('aivOr').value.trim();if(rs.length<5){document.getElementById('aivOr').focus();return}ok.disabled=true;fetch('/admin/orders/'+cur+'/ai-verify/override',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':tok()},body:JSON.stringify({status:document.getElementById('aivOs').value,reason:rs})}).then(function(x){return x.json()}).then(function(j){render(j);upd(j)}).catch(function(){ok.disabled=false})};
}
function upd(r){document.querySelectorAll('.ai-btn[data-id="'+r.order_id+'"]').forEach(function(b){paint(b,r.status,r.score)})}
function load(id,run){cur=id;open();B.innerHTML='<div class="aiv-ld">Verifying order #'+id+' …<br>Checking customer, fraud, payment, stock, pricing and history</div>';document.getElementById('aivSub').textContent='Order #'+id;var tl=document.getElementById('aivT');if(tl)tl.href='/admin/orders/'+id+'/ai-verify/page';
fetch('/admin/orders/'+id+'/ai-verify'+(run?'?run=1':''),{headers:{Accept:'application/json'}}).then(function(x){if(!x.ok)throw 0;return x.json()}).then(function(j){render(j);upd(j)}).catch(function(){B.innerHTML='<div class="aiv-ld">Could not run AI Verify. Please try again.</div>'})}
document.addEventListener('click',function(e){var b=e.target.closest('.ai-btn');if(b){e.preventDefault();load(parseInt(b.getAttribute('data-id'),10),false)}});
document.getElementById('aivRe').onclick=function(){if(cur)load(cur,true)};
var ids=[].map.call(document.querySelectorAll('.ai-btn[data-id]'),function(b){return b.getAttribute('data-id')});
function stat(n){if(!ids.length)return;fetch('/admin/orders/ai-status?ids='+ids.join(','),{headers:{Accept:'application/json'}}).then(function(x){return x.json()}).then(function(j){var m=j.m||{};document.querySelectorAll('.ai-btn[data-id]').forEach(function(b){var v=m[b.getAttribute('data-id')];if(v)paint(b,v.s,v.n)});if(j.left>0&&n<8)setTimeout(function(){stat(n+1)},800)}).catch(function(){})}
stat(0);setInterval(function(){if(!document.hidden)stat(0)},60000);
var pgE=document.querySelector('[data-aipage]');if(pgE){document.body.classList.add('aipg');dr.classList.add('pg');load(parseInt(pgE.getAttribute('data-aipage'),10),false)}
})();</script>
